33|// Scene illustration state: the client sends ordinals and ids only,
34|// never text. The scene id comes from the route, never from a DOM scan.
35|// The image survives sub-page moves and clears on scene change because
36|// the scene view remounts per scene id.
37|export function usePictureScene({
38|  bookId,
39|  textVersion,
40|  sceneId,
41|}: {
42|  bookId: string;
43|  textVersion: string;
44|  sceneId: string;
45|}) {
46|  const [card, setCard] = useState<PictureCard>({ phase: "idle" });
47|  const [popover, setPopover] = useState<{ top: number; left: number } | null>(null);
48|  const viewRef = useRef<HTMLDivElement | null>(null);
49|  const popRef = useRef<HTMLButtonElement | null>(null);
50|  const pollLeft = useRef(0);
51|
52|  const hidePopover = useCallback(() => setPopover(null), []);
53|
54|  const request = useCallback(async (body: unknown) => {
55|    setPopover(null);
56|    setCard({ phase: "loading" });
57|    pollLeft.current = POLL_MAX;
58|    for (;;) {
59|      let res: ImageResponse;
60|      try {
61|        res = await postImage(body);
62|      } catch {
63|        setCard({ phase: "error", message: MSG_FAILED });
64|        return;
65|      }
66|      if (res.status === "ready") {
67|        setCard({ phase: "ready", url: res.url, caption: res.caption, cached: res.cached });
68|        return;
69|      }
70|      if (res.status === "error") {
71|        setCard({ phase: "error", message: res.message });
72|        return;
73|      }
74|      pollLeft.current -= 1;
75|      if (pollLeft.current <= 0) {
76|        setCard({ phase: "error", message: MSG_RETRY });
77|        return;
78|      }
79|      await new Promise((done) => setTimeout(done, POLL_MS));
80|    }
81|  }, []);
82|
83|  const illustrateScene = useCallback(() => {
84|    if (!sceneId || card.phase === "loading") return;
85|    void request({ kind: "scene", bookId, textVersion, sceneId });
86|  }, [bookId, textVersion, sceneId, request, card.phase]);
87|
88|  const illustratePassage = useCallback(() => {
89|    const view = viewRef.current;
90|    const sel = window.getSelection();
91|    if (!view || !sel || !sel.rangeCount) return;
92|    const entries: ParaEntry[] = [...view.querySelectorAll("p[id][data-n]")].map((el) => ({
93|      id: el.id,
94|      n: Number(el.getAttribute("data-n")),
95|    }));
96|    const n = pickStartN(entries, paraOf(sel.anchorNode)?.id ?? null, paraOf(sel.focusNode)?.id ?? null);
97|    if (n === null || !Number.isInteger(n) || card.phase === "loading") return;
98|    void request({ kind: "passage", bookId, textVersion, n });
99|  }, [bookId, textVersion, request, card.phase]);
100|
101|  const dismissCard = useCallback(() => setCard({ phase: "idle" }), []);
102|
103|  // "Picture this" popover: on mouseup, after a frame, show it above the
104|  // selection when the trimmed text is at least 3 chars inside the scene.
105|  // Hidden while an image loads.
106|  useEffect(() => {
107|    const view = viewRef.current;
108|    if (!view) return;
109|    let frame = 0;
110|    const onMouseUp = () => {
111|      cancelAnimationFrame(frame);
112|      frame = requestAnimationFrame(() => {
113|        const sel = window.getSelection();
114|        const text = sel?.toString().trim() ?? "";
115|        if (!sel || sel.isCollapsed || text.length < 3 || !sel.rangeCount) {
116|          setPopover(null);
117|          return;
118|        }
119|        if (!view.contains(sel.anchorNode) || !view.contains(sel.focusNode)) {
120|          setPopover(null);
121|          return;
122|        }
123|        const box = sel.getRangeAt(0).getBoundingClientRect();
124|        const host = view.getBoundingClientRect();
125|        setPopover({
126|          top: box.top - host.top - 8,
127|          left: box.left - host.left + box.width / 2,
128|        });
129|      });
130|    };
131|    view.addEventListener("mouseup", onMouseUp);
132|    return () => {
133|      cancelAnimationFrame(frame);
134|      view.removeEventListener("mouseup", onMouseUp);
135|    };
136|  }, [sceneId]);
137|
138|  // Any mousedown outside the popover dismisses it, as does Escape.
139|  useEffect(() => {
140|    if (!popover) return;
141|    const onDown = (event: MouseEvent) => {
142|      if (!popRef.current?.contains(event.target as Node | null)) setPopover(null);
143|    };
144|    const onKey = (event: KeyboardEvent) => {
145|      if (event.key === "Escape") setPopover(null);
146|    };
147|    document.addEventListener("mousedown", onDown);
148|    document.addEventListener("keydown", onKey);
149|    return () => {
150|      document.removeEventListener("mousedown", onDown);
151|      document.removeEventListener("keydown", onKey);
152|    };
153|  }, [popover]);
154|
155|  const loading = card.phase === "loading";
156|  return {
157|    card,
158|    popover: loading ? null : popover,
159|    viewRef,
160|    popRef,
161|    illustrateScene,
162|    illustratePassage,
163|    hidePopover,
164|    dismissCard,
165|  };
166|}
