84|export interface BookRef {
85|  id: string;
86|  textVersion: string;
87|  paragraphNs: Set<number>;
88|  sceneIds: Set<string>;
89|}
90|
91|// Checks the parsed request against the frozen book text.
92|export function validateAgainstBook(req: ImageRequest, book: BookRef): void {
93|  if (req.bookId !== book.id) throw new ImageValidationError();
94|  if (req.textVersion !== book.textVersion) throw new ImageValidationError();
95|  if (req.kind === "passage") {
96|    if (!book.paragraphNs.has(req.n)) throw new ImageValidationError();
97|    return;
98|  }
99|  if (!book.sceneIds.has(req.sceneId)) throw new ImageValidationError();
100|}
101|
102|// One paragraph maps to one image; one scene maps to one image.
103|export function imageKey(req: ImageRequest): string {
104|  const base = `images/${req.bookId}/${req.textVersion}/${PROMPT_VERSION}`;
105|  return req.kind === "passage" ? `${base}/p${req.n}.webp` : `${base}/scene-${req.sceneId}.webp`;
106|}
107|
108|export function indexKeyFor(key: string): string {
109|  return `img:index:${key}`;
110|}
111|
112|export function lockKeyFor(key: string): string {
113|  return `img:lock:${key}`;
114|}
115|
116|export function quotaKeys(args: { day: string; ipHash: string; anonId: string }): {
117|  ip: string;
118|  anon: string;
119|} {
120|  return {
121|    ip: `img:quota:ip:${args.day}:${args.ipHash}`,
122|    anon: `img:quota:anon:${args.day}:${args.anonId}`,
123|  };
124|}
125|
126|export function spendKey(): string {
127|  return "img:spend:micro";
128|}
129|
130|export function overQuota(count: number): boolean {
131|  return count > DAILY_IMAGE_LIMIT;
132|}
133|
134|export function budgetExceeded(totalAfterReserve: number, capMicro: number): boolean {
135|  return totalAfterReserve > capMicro;
136|}
137|
138|export function imageCostMicro(): number {
139|  return IMAGE_COST_MICRO;
140|}
141|
142|// Lets the route compare lock tokens without touching Redis twice.
143|export function canRelease(expected: string, actual: string | null): boolean {
144|  return actual !== null && actual === expected;
145|}
146|
147|function clip(text: string, max: number): string {
148|  const clean = text.replace(/\s+/g, " ").trim();
149|  if (clean.length <= max) return clean;
150|  return clean.slice(0, max).trimEnd();
151|}
152|
153|// Prompt from trusted server-side book text only. The client sends
154|// ordinals and ids, never free text, so there is no injection path.
155|export function buildPrompt(args: {
156|  kind: ImageKind;
157|  passageText: string;
158|  sceneTitle: string;
159|  sceneClip: string;
160|}): string {
161|  const style =
162|    "Illustration in the style of W. W. Denslow's 1900 first-edition " +
163|    "illustrations for The Wonderful Wizard of Oz: flat color, bold black " +
164|    "ink outlines, limited palette. Dorothy wears silver shoes. Nothing " +
165|    "from the 1939 MGM film, no ruby slippers, no film look. No text, " +
166|    "no captions, no lettering in the image.";
167|  if (args.kind === "scene") {
168|    return (
169|      `Scene "${args.sceneTitle}". ${clip(args.sceneClip, MAX_SCENE_CLIP_CHARS)}. ${style}`
170|    );
171|  }
172|  return (
173|    `Scene "${args.sceneTitle}". Passage: ${clip(args.passageText, MAX_PASSAGE_CHARS)}. ` +
174|    `Context: ${clip(args.sceneClip, MAX_SCENE_CLIP_CHARS)}. ${style}`
175|  );
176|}
177|
178|export function buildCaption(args: {
179|  kind: ImageKind;
180|  sceneTitle: string;
181|  passageText: string;
182|}): string {
183|  if (args.kind === "scene") return args.sceneTitle;
184|  const words = args.passageText.replace(/\s+/g, " ").trim().split(" ").slice(0, 10);
185|  const head = words.join(" ");
186|  return words.length >= 10 ? `${head}…` : head;
187|}
188|
189|// In-memory KV for tests. Expiries are checked against Date.now.
190|export function createMemoryKV(): KV & { clear(): void } {
191|  const values = new Map<string, string>();
192|  const expiresAt = new Map<string, number>();
193|  function live(key: string): boolean {
194|    const until = expiresAt.get(key);
195|    if (until !== undefined && Date.now() >= until) {
196|      values.delete(key);
197|      expiresAt.delete(key);
198|      return false;
199|    }
200|    return true;
201|  }
202|  function num(key: string): number {
203|    return Number(values.get(key) ?? "0");
204|  }
205|  return {
206|    async get(key: string): Promise<string | null> {
207|      if (!live(key)) return null;
208|      return values.get(key) ?? null;
209|    },
210|    async setNxEx(key: string, value: string, exSec: number): Promise<boolean> {
211|      if (live(key) && values.has(key)) return false;
212|      values.set(key, value);
213|      expiresAt.set(key, Date.now() + exSec * 1000);
214|      return true;
215|    },
216|    async set(key: string, value: string): Promise<void> {
217|      values.set(key, value);
218|      expiresAt.delete(key);
219|    },
220|    async incr(key: string): Promise<number> {
221|      const next = num(key) + 1;
222|      values.set(key, String(next));
223|      return next;
224|    },
225|    async incrBy(key: string, by: number): Promise<number> {
226|      const next = num(key) + by;
227|      values.set(key, String(next));
228|      return next;
229|    },
230|    async decr(key: string): Promise<number> {
231|      const next = num(key) - 1;
232|      values.set(key, String(next));
233|      return next;
234|    },
235|    async decrBy(key: string, by: number): Promise<number> {
236|      const next = num(key) - by;
237|      values.set(key, String(next));
238|      return next;
239|    },
240|    async expire(key: string, sec: number): Promise<void> {
241|      if (values.has(key)) expiresAt.set(key, Date.now() + sec * 1000);
242|    },
243|    async releaseIfToken(key: string, token: string): Promise<boolean> {
244|      if (!live(key)) return false;
245|      if (values.get(key) !== token) return false;
246|      values.delete(key);
247|      expiresAt.delete(key);
248|      return true;
249|    },
250|    clear(): void {
251|      values.clear();
252|      expiresAt.clear();
253|    },
254|  };
255|}

