15|function toResponse(res: ImageResponse): { json: ImageResponse; status: number } {
16|  if (res.status === "ready" || res.status === "pending") return { json: res, status: 200 };
17|  const status = res.code === "bad_request" ? 400 : res.code === "quota" ? 429 : 503;
18|  return { json: res, status };
