21|export async function handleImagesPost(req: Request): Promise<Response> {
22|  const capped = await readBodyCapped(req, MAX_IMAGE_BODY_BYTES);
23|  if (!capped.ok) {
24|    return Response.json(
25|      { status: "error", code: "bad_request", message: MSG_BAD_REQUEST } satisfies ImageResponse,
26|      { status: capped.reason === "too_large" ? 413 : 400 },
27|    );
28|  }
29|
30|  let parsed: ImageRequest;
31|  try {
32|    parsed = parseImageRequest(JSON.parse(capped.text));
33|  } catch {
34|    return Response.json(
35|      { status: "error", code: "bad_request", message: MSG_BAD_REQUEST } satisfies ImageResponse,
36|      { status: 400 },
37|    );
38|  }
39|
40|  let env;
41|  try {
42|    env = readImageEnv();
43|  } catch (e) {
44|    const message = e instanceof Error ? e.message : "";
45|    const prefix = "missing image env:";
46|    const names = message.startsWith(prefix) ? message.slice(prefix.length).trim() : "";
47|    console.warn(`image env missing: ${names}`);
48|    return Response.json(
49|      { status: "error", code: "unavailable", message: MSG_UNAVAILABLE } satisfies ImageResponse,
50|      { status: 503 },
51|    );
52|  }
53|
54|  try {
55|    const { book, scenes } = loadOzBook();
56|    try {
57|      validateAgainstBook(
58|        parsed,
59|        {
60|          id: book.id,
61|          textVersion: book.textVersion,
62|          paragraphNs: new Set(book.paragraphs.map((p) => p.n)),
63|          sceneIds: new Set(scenes.map((s) => s.id)),
64|        },
65|      );
66|    } catch {
67|      return Response.json(
68|        { status: "error", code: "bad_request", message: MSG_BAD_REQUEST } satisfies ImageResponse,
