1|import "server-only";
2|import { randomUUID } from "node:crypto";
3|import {
4|  MSG_FAILED,
5|  MSG_QUOTA,
6|  MSG_BUDGET,
7|  LOCK_TTL_SEC,
8|  buildCaption,
9|  buildPrompt,
10|  budgetExceeded,
11|  imageCostMicro,
12|  imageKey,
13|  indexKeyFor,
14|  lockKeyFor,
15|  spendKey,
16|} from "@/core/images";
17|import type { ImageGenerator, ImageRequest, ImageResponse, ImageStore, KV } from "@/core/images";
18|import type { ImageEnv } from "./env";
19|import { verifyHuman } from "./human";
20|import { checkQuota, hashIp, quotaKeysFor, refundQuota } from "./quota";
21|
22|export interface ImageContent {
23|  passageText: string;
24|  sceneTitle: string;
25|  sceneClip: string;
26|}
27|
28|export interface OrchestrateDeps {
29|  kv: KV;
30|  store: ImageStore;
31|  generate: ImageGenerator;
32|  env: ImageEnv;
33|  content: ImageContent;
34|  ip: string;
35|  anonId: string;
36|  day: string;
37|  token?: string;
38|}
39|
40|// One pass, no skipped steps: hit -> lock -> human -> quota -> budget ->
41|// generate -> store -> index -> release. Every failure after the reserve
42|// refunds quota and budget and releases the lock.
43|export async function orchestrate(
44|  req: ImageRequest,
45|  deps: OrchestrateDeps,
46|): Promise<ImageResponse> {
47|  const key = imageKey(req);
48|  const indexKey = indexKeyFor(key);
49|  const lockKey = lockKeyFor(key);
50|
51|  const indexed = await deps.kv.get(indexKey);
52|  if (indexed) {
53|    return { status: "ready", url: indexed, cached: true, caption: captionFor(req, deps.content) };
54|  }
55|  const existing = await deps.store.findUrl(key);
56|  if (existing) {
57|    await deps.kv.set(indexKey, existing);
58|    return { status: "ready", url: existing, cached: true, caption: captionFor(req, deps.content) };
59|  }
60|
61|  const token = deps.token ?? randomUUID();
62|  if (!(await deps.kv.setNxEx(lockKey, token, LOCK_TTL_SEC))) return { status: "pending" };
63|
64|  // Best-effort unlock: a release failure must never turn into a client 500.
65|  const release = async (): Promise<void> => {
66|    try {
67|      await deps.kv.releaseIfToken(lockKey, token);
68|    } catch {
69|      // Lock expires on its own; nothing to do.
70|    }
71|  };
72|
73|  const keys = quotaKeysFor({ day: deps.day, ip: deps.ip, salt: deps.env.ipSalt, anonId: deps.anonId });
74|  let quotaTaken = false;
75|  let spendTaken = false;
76|  // Best-effort refunds that clear their flag only after the write lands,
77|  // so the outer catch refunds each reserve exactly once.
78|  const refundQuotaOnce = async (): Promise<void> => {
79|    try {
80|      await refundQuota(deps.kv, keys);
81|      quotaTaken = false;
82|    } catch {
83|      // Redis down: nothing reserved server-side to retry against.
84|    }
85|  };
86|  const refundSpendOnce = async (): Promise<void> => {
87|    try {
88|      await deps.kv.decrBy(spendKey(), imageCostMicro());
89|      spendTaken = false;
90|    } catch {
91|      // Redis down: nothing reserved server-side to retry against.
92|    }
93|  };
94|
95|  try {
96|    if (!verifyHuman()) {
97|      await release();
98|      return { status: "error", code: "unavailable", message: MSG_FAILED };
99|    }
100|
101|    if (!(await checkQuota(deps.kv, keys)).ok) {
102|      await release();
103|      return { status: "error", code: "quota", message: MSG_QUOTA };
104|    }
105|    quotaTaken = true;
106|
107|    const total = await deps.kv.incrBy(spendKey(), imageCostMicro());
108|    spendTaken = true;
109|    if (budgetExceeded(total, deps.env.spendCapMicro)) {
110|      await refundSpendOnce();
111|      await refundQuotaOnce();
112|      await release();
113|      return { status: "error", code: "budget", message: MSG_BUDGET };
114|    }
115|
116|    let bytes: Uint8Array;
117|    try {
118|      bytes = await deps.generate.generate(
119|        buildPrompt({
120|          kind: req.kind,
121|          passageText: deps.content.passageText,
122|          sceneTitle: deps.content.sceneTitle,
123|          sceneClip: deps.content.sceneClip,
124|        }),
125|      );
126|    } catch {
127|      await refundSpendOnce();
128|      await refundQuotaOnce();
129|      await release();
130|      console.error("image generate failed");
131|      return { status: "error", code: "unavailable", message: MSG_FAILED };
132|    }
133|
134|    try {
135|      const url = await deps.store.save(key, bytes);
136|      try {
137|        await deps.kv.set(indexKey, url);
138|      } catch {
139|        console.error("image index failed");
140|        await release();
141|        return { status: "ready", url, cached: false, caption: captionFor(req, deps.content) };
142|      }
143|      await release();
144|      return { status: "ready", url, cached: false, caption: captionFor(req, deps.content) };
145|    } catch {
146|      // A lost save race leaves the winner's file behind; backfill from it.
147|      const raced = await deps.store.findUrl(key);
148|      if (raced) {
149|        try {
150|          await deps.kv.set(indexKey, raced);
151|        } catch {
152|          console.error("image index failed");
153|        }
154|        await release();
155|        return { status: "ready", url: raced, cached: true, caption: captionFor(req, deps.content) };
156|      }
157|      await refundSpendOnce();
158|      await refundQuotaOnce();
159|      await release();
160|      console.error("image store failed");
161|      return { status: "error", code: "unavailable", message: MSG_FAILED };
162|    }
163|  } catch {
164|    if (spendTaken) await refundSpendOnce();
165|    if (quotaTaken) await refundQuotaOnce();
166|    await release();
167|    console.error("image request failed");
168|    return { status: "error", code: "unavailable", message: MSG_FAILED };
169|  }
170|}
